#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,q,cs=0;
    while (cin >> n >> q && (n||q)) {
        vector<int> a(n);
        for (auto &x : a) cin >> x;
        sort(a.begin(), a.end());
        cout << "CASE# " << ++cs << ":\n";
        for (int i=0;i<q;i++){
            int x; cin >> x;
            auto it = lower_bound(a.begin(), a.end(), x);
            if (it != a.end() && *it == x) cout << x << " found at " << (it-a.begin()+1) << "\n";
            else cout << x << " not found\n";
        }
    }
}

